import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import DiscussionHero from 'flarum/forum/components/DiscussionHero';
import LinkButton from 'flarum/common/components/LinkButton';
import UserPage from 'flarum/forum/components/UserPage';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import { registerModels } from '../common/models';
import registerWidgets from './widgets';
import collector from './collector';
import { t } from './util';
import { applyShowOff } from './showOff';
import { FOLLOWED } from './components/notifications';
/** Loaded the first time a "Show it off" discussion is opened, never with other pages. */
let ItemHero = null;
let heroLoading = null;
const loadHero = () => heroLoading ??= import(/* webpackChunkName: 'forum/components/ItemHero', webpackMode: 'lazy-once' */ './components/ItemHero').then(module => {
  ItemHero = module.default;
  m.redraw();
});
const myCollections = () => app.route('user.curio', {
  username: app.session.user.slug()
});
/** "My collections" goes where the admin chose: the sidebar, the account menu, both or neither. */
const shortcutIn = place => ['both', place].includes(app.forum.attribute('curioShortcut') ?? 'both');
app.initializers.add('ernestdefoe-curio', () => {
  registerModels(app);
  collector();

  // Pages load on first visit, never with every forum page.
  app.routes['curio.browse'] = {
    path: '/collections',
    component: () => import(/* webpackChunkName: 'forum/components/BrowsePage', webpackMode: 'lazy-once' */ './components/BrowsePage')
  };
  app.routes['curio.collection'] = {
    path: '/collections/:id',
    component: () => import(/* webpackChunkName: 'forum/components/CollectionPage', webpackMode: 'lazy-once' */ './components/CollectionPage')
  };
  app.routes['user.curio'] = {
    path: '/u/:username/collections',
    component: () => import(/* webpackChunkName: 'forum/components/UserCollectionsPage', webpackMode: 'lazy-once' */ './components/UserCollectionsPage')
  };
  extend(UserPage.prototype, 'navItems', function (items) {
    if (!this.user || !app.forum.attribute('canViewCurio')) return;
    items.add('curio', m(LinkButton, {
      href: app.route('user.curio', {
        username: this.user.slug()
      }),
      icon: "fas fa-boxes-stacked"
    }, t('profile.nav')), 85);
  });
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (!app.forum.attribute('canViewCurio')) return;
    items.add('curio', m(LinkButton, {
      href: app.route('curio.browse'),
      icon: "fas fa-boxes-stacked"
    }, t('browse.title')), 85);
    // One click to your own collections (instead of Profile → Collections).
    if (app.session.user && app.forum.attribute('canCreateCurio') && shortcutIn('sidebar')) {
      items.add('curioMine', m(LinkButton, {
        href: myCollections(),
        icon: "fas fa-box-archive"
      }, t('nav.mine')), 84);
    }
  });
  extend('flarum/forum/components/SessionDropdown', 'items', function (items) {
    if (!app.forum.attribute('canCreateCurio') || !shortcutIn('menu')) return;
    items.add('curio', m(LinkButton, {
      href: myCollections(),
      icon: "fas fa-boxes-stacked"
    }, t('nav.mine')), 95);
  });

  // "Show it off": the composer carries the item it was opened for.
  extend('flarum/forum/components/DiscussionComposer', 'oncreate', function () {
    applyShowOff(this.composer);
  });
  extend('flarum/forum/components/DiscussionComposer', 'headerItems', function (items) {
    const item = this.composer.fields.curioItem;
    if (!item) return;
    items.add('curio', m("span", {
      className: "CurioComposerItem"
    }, item.cover ? m("img", {
      src: item.cover,
      alt: ""
    }) : null, t('showoff.composer', {
      title: m("b", null, item.title)
    }), m("button", {
      type: "button",
      className: "Button Button--icon Button--link",
      "aria-label": t('showoff.remove'),
      onclick: () => this.composer.fields.curioItem = null
    }, m("i", {
      className: "fas fa-times",
      "aria-hidden": "true"
    }))), -10);
  });
  extend('flarum/forum/components/DiscussionComposer', 'data', function (data) {
    const item = this.composer.fields.curioItem;
    if (item) data.curioItemId = Number(item.id);
  });

  // Its discussion page opens with the item as the hero (unless Marquee already has the hero).
  override(DiscussionHero.prototype, 'view', function (original) {
    const discussion = this.attrs.discussion;
    const item = discussion.curioItem && discussion.curioItem();
    if (!item || discussion.marqueeMedia && discussion.marqueeMedia()) return original();
    if (!ItemHero) {
      loadHero();
      return original();
    }
    return m(ItemHero, {
      discussion: discussion,
      item: item
    });
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', items => {
    items.add('curioWishlistMatch', {
      name: 'curioWishlistMatch',
      icon: 'fas fa-right-left',
      label: t('notifications.match_setting')
    });
    FOLLOWED.forEach(([name, component]) => items.add(name, {
      name,
      icon: component.iconName,
      label: t(`notifications.${component.key}_setting`)
    }));
  });
  extendMarquee();
  registerWidgets();
});

/**
 * With Marquee installed, its cards get "Add to collection" (or "Edit" once
 * the reader has the title) and how many members have it. Found at run time,
 * so Curio works the same without it. What the reader has comes with the
 * discussion page (curioMarquee); the windows load on hover or click.
 */
/** A related title's card info, asked for once when a reader first switches Marquee's card to it. */
const relatedCards = new Map();
function relatedCard(media) {
  const key = `${media.kind()}:${media.externalId()}`;
  if (!relatedCards.has(key)) {
    relatedCards.set(key, null);
    app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/curio/marquee-card`,
      params: {
        kind: media.kind(),
        id: media.externalId()
      },
      errorHandler() {}
    }).then(payload => {
      relatedCards.set(key, payload.data);
      m.redraw();
    }, () => {});
  }
  // Stands in for the discussion, so adding or editing a copy updates this title's buttons.
  return {
    attribute: () => relatedCards.get(key),
    pushAttributes: ({
      curioMarquee
    }) => relatedCards.set(key, curioMarquee)
  };
}
function extendMarquee() {
  const mod = globalThis.flarum?.reg?.get?.('ernestdefoe-marquee', 'forum/components/MediaHero');
  const MediaHero = mod?.default ?? mod;
  if (!MediaHero?.prototype?.actionItems) return;
  const later = (name, ...args) => import(/* webpackChunkName: 'forum/fromMarquee', webpackMode: 'lazy-once' */ './fromMarquee').then(module => module[name](...args));
  extend(MediaHero.prototype, 'actionItems', function (items) {
    const media = this.attrs.link?.media;
    if (!media || !app.forum.attribute('canViewCurio')) return;
    // What the page says about the reader's copy is for the linked title. A related
    // title shown in its place (a series) asks for its own.
    const main = this.attrs.discussion?.marqueeMedia?.();
    const discussion = !main || media === main ? this.attrs.discussion : relatedCard(media);
    const card = discussion?.attribute('curioMarquee');
    const source = this.attrs.discussion?.attribute('curioMarquee')?.source;
    // Already in one of the reader's collections: edit that copy instead of adding another.
    // A copy only on their wishlist shows as a filled heart; the editor moves it to the shelf.
    const editing = !!(card?.itemId && app.session.user);
    const wished = editing && !card.owning;
    if (editing || app.session.user && app.forum.attribute('canCreateCurio')) {
      const warm = () => later('warm', editing);
      items.add('curio', m(Button, {
        className: 'Button CurioMarqueeButton' + (wished ? ' CurioMarqueeButton--wished' : ''),
        icon: wished ? 'fas fa-heart' : editing ? 'fas fa-pen' : 'fas fa-boxes-stacked',
        onpointerenter: warm,
        onfocus: warm,
        onclick: () => later(editing ? 'edit' : 'add', media, discussion, 'owned', source)
      }, t(wished ? 'marquee.on_wishlist' : editing ? 'marquee.edit' : 'marquee.add')), 65);
      if (!editing) {
        items.add('curioWish', m(Button, {
          className: "Button Button--icon CurioMarqueeButton",
          icon: "far fa-heart",
          title: t('marquee.wish'),
          "aria-label": t('marquee.wish'),
          onpointerenter: warm,
          onfocus: warm,
          onclick: () => later('add', media, discussion, 'wishlist', source)
        }), 65);
      }
    }
    if (card?.workId && card.owners) {
      items.add('curioOwners', m(Button, {
        className: "Button CurioMarqueeButton",
        icon: "fas fa-users",
        onclick: () => later('ownersOf', card.workIds || card.workId, media.title())
      }, t('hero.members', {
        count: card.owners
      })), 64);
    }
  });
}flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/ItemHero', '123', 'ernestdefoe-curio', 'forum/components/ItemHero');
